import http = require('http');
import {uploadToServer, closeServer} from 'jibo-sync';

const DEV_SHELL_PORT = 8686;
const SYNC_PORT = 8989;
const SYNC_SKILL_URL = '/sync-skill';
const RUN_URL = '/run';
const STOP_URL = '/stop';
const DISKSPACE_URL = '/diskspace';
const REBOOT_URL = '/reboot';
const POWEROFF_URL = '/poweroff';
const VERSION_URL = '/version';
const INDEX_URL = '/index';
const SETVOLUME_URL = '/setvolume';
const GETVOLUME_URL = '/getvolume';
const DELETE_URL = '/delete-skill';
const CHECK_UPDATE_URL = '/check-update';
const DOWNLOAD_UPDATE_URL = '/download-update';
const INSTALL_UPDATE_URL = '/install-update';

export function syncSkill(host, skillPath, skillName, verbose, cb) {
    let data = {
        'dirName': skillName
    };

    _sendRequest(host, SYNC_SKILL_URL, data, (error, msg) => {
        if (error) {
            cb(error, msg);
        }
        else {
            // start uploading to sync server
            let syncUrl = host + ":" + SYNC_PORT;

            let closeServerWhenDone = false;
            uploadToServer(syncUrl, skillPath, closeServerWhenDone, verbose, cb);
        }
    });
}

export function stopSync(host, cb) {
    // tell sync server to close
    let syncUrl = host + ":" + SYNC_PORT;
    closeServer(syncUrl, cb);
}


export function runSkill(host, skillName, cb) {

    let data = {
      'dirName': skillName
    };

    _sendRequest(host, RUN_URL, data, cb);
}


export function stopSkill(host, cb) {

    _sendRequest(host, STOP_URL, undefined, cb);
}


export function getBuildVersion(host, cb) {

    _sendRequest(host, VERSION_URL, undefined, cb);
}


export function getVolume(host, cb) {

    _sendRequest(host, GETVOLUME_URL, undefined, cb);
}


export function setVolume(host, _volume, cb) {

    // Did they give you a value?
    if (!_volume) {
        cb('No volume specified. Please specify a volume in the range [0.0-1.0].', null);
        return;
    }

    // Make sure the volume is parse-able as a number
    let vol = parseFloat(_volume);
    if(Number.isNaN(vol)){
        cb('Volume "' + _volume + '" is not a number.', null);
        return;
    }

    // Is it in the correct range
    if( vol < 0.0 ||
        vol > 1.0){
        cb('Volume must be in the range [0.0-1.0]. Was ' + vol + '.', null);
        return;
    }


    let data = {
        "volume" : vol
    };

    _sendRequest(host, SETVOLUME_URL, data, cb);
}


export function getDiskSpace(host, cb) {

    _sendRequest(host, DISKSPACE_URL, undefined, cb);
}


export function rebootRobot(host, cb) {

    _sendRequest(host, REBOOT_URL, undefined, cb);
}


export function powerOffRobot(host, cb) {

    _sendRequest(host, POWEROFF_URL, undefined, cb);
}


export function indexRobot(host, cb) {

    _sendRequest(host, INDEX_URL, undefined, cb);
}


export function deleteSkill(host, skillName, cb) {

    let data = {
        'dirName': skillName
    };

    _sendRequest(host, DELETE_URL, data, cb);
}

export function checkForUpdates(host, filter, cb) {

    let options = {
        filter
    };
    _sendRequest(host, CHECK_UPDATE_URL, options, cb);
}

export function downloadUpdates(host, ids, cb) {

    let otaData = {
        ids
    };

    _sendRequest(host, DOWNLOAD_UPDATE_URL, otaData, (error, data) => {

        if(error || data.status === 'failed' || data.error){
            return cb(error || data.reason || data.error);
        }

        cb(null, data);
    });
}

export function getOTASocketUrl(host): string {
    // return the url for the ota download socket
    return 'ws://' + host + ':' + DEV_SHELL_PORT + '/download-update';
}

export function installUpdates(host, ids, cb) {

    let otaData = {
        ids
    };

    _sendRequest(host, INSTALL_UPDATE_URL, otaData, (error, data) => {

        if(error || data.status === 'failed' || data.error){
            return cb(error || data.reason || data.error);
        }

        cb(null, data);
    });
}

function _sendRequest(host, urlPath, _data, cb) {
    let body = (_data ? _data : {});
    try {
        body = JSON.stringify(body);
    }
    catch(e) {
        cb('Attempting to send invalid data to dev shell. Request is not valid JSON', null);
        return;
    }

    let options = {
        hostname: host,
        port: DEV_SHELL_PORT,
        path: urlPath,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        }
    };
    let req = http.request(options, (res) => {
        let str = '';
        res.on('data', (chunk) => {
            str += chunk;
        });

        res.on('end', () => {
            let body = undefined;
            try {
                body = JSON.parse(str);
            }
            catch (e) {
                cb('Invalid request to dev shell. Request body is not valid JSON: ' + str, null);
                return;
            }

            if (body.Status === 'ERROR') {
                cb(body.Message, null);
            }
            else {
                cb(null, body.Message);
            }
        });
    });

    req.on('error', () => {
        cb('Dev shell is not available on ' + host, null);
    });

    req.write(body);
    req.end();
}

