import {runSkill} from './dev-shell';
/**
 * Run a skill on the robot.
 * @method module:jibo-cli.run
 * @param {RobotInfo} robotInfo The robot to run the skill on.
 * @param {String} skillName Name of the skill to run on the robot. This is is just
 *                           appended to `/jibo/skills/<skillName>` as all skills are
 *                           organized in a flat directory in `/jibo/skills`.
 */
function run(robotInfo, skillName, cb){

    runSkill(robotInfo.ip, skillName, (error, msg) => {
        cb(error, msg);
    });
}

export default run;
