import Command from '../command';
let Spinner = require('cli-spinner').Spinner;
let WebSocket = require('ws-without-native');

/**
 * Updates the robot.
 * @class UpdateRobot
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class UpdateRobot extends Command {
    private _robotInfo:any;
    private _spinner:typeof Spinner;
    private _updateIDs:Array<string>;
    private _otaSocket:any;
    private _downloadedIDs:Array<string>;

    parse() {
        this.program
            .option('-r, --robot <robotName>', 'Target robot')
            .option('-f, --filter <string>', 'Optional filter for updates')
           // @TODO- .option('-n, --noskill', 'If set, do not update any skills')
            .parse(process.argv);
    }

    exec() {
        this.isRobotReachable(this.program.robot, "Attempting to update %s.", (robotInfo) => {
            this._robotInfo = robotInfo;

            this._spinner = new Spinner('checking for updates... %s');
            this._spinner.start();

            // retrieve update list
            this.tools.updateRobot.get(this._robotInfo, this.program.filter, (err, response) => {

                // stop spinner and show response
                this._spinner.stop(true);

                // if errors, bail out here
                if (err || !response || !response.data) {
                    let msg = err;
                    if (!response && this.program.filter) {      // handle gracefully on older builds that don't support filter
                        msg = 'Unrecognized update filter';
                    }
                    return this.error(msg);
                }

                // bail out early if no updates found
                if (response.data && response.data.length === 0) {
                    this.red("No updates found");
                    return;
                }
                else {
                    this.green(response.msg);
                }

                // create websocket for downloading updates
                let socketUrl = this.tools.updateRobot.getOTASocketUrl(this._robotInfo);
                this._otaSocket = new WebSocket(socketUrl);
                this._otaSocket.onerror = () => {
                    console.log("Error opening ota download socket");
                };
                this._otaSocket.on('message', this._downloadStatus.bind(this));

                // this._otaSocket.onclose = () => {
                //     console.log("closing socket");
                // };

                //reset our downloaded IDs
                this._downloadedIDs = [];

                // create an array of updateIDs to pass to system manager's download API
                this._updateIDs = [];
                const count = response.data.length;
                for(let i =0; i<count; ++i) {
                    const dlData = response.data[i];
                    // if any are already downloaded, mark it as such
                    if (dlData.downloaded) {
                        this._downloadedIDs.push(dlData.id);
                    }

                    this._updateIDs.push(dlData.id);
                }

                // start download!
                this._startNextDownload((error) => {

                    this._spinner.stop(true);
                    this._closeOTASocket();

                    if (error) {
                        return this.error(error);
                    }

                    // start installation
                    this._spinner.setSpinnerTitle('installing updates... ' + '%s');
                    this._spinner.start();

                    // 3. install updates
                    this.tools.updateRobot.install(this._robotInfo, this._updateIDs, (err, response) => {
                        this._spinner.stop(true);

                        if (err) {
                            return this.error(err);
                        }
                        this.success(response);

                        // tell them wait until reboots are over
                    });
                });
            });
        });
    }

    _startNextDownload(cb) {
        // clear it
        this._spinner.stop(true);

        // get next update ID
        let nextId = null;
        const updateLen = this._updateIDs.length;
        if (updateLen !== this._downloadedIDs.length) {
            for (let updateIdx = 0; updateIdx < updateLen; updateIdx++) {
                // if we find that one of our updatedIDs do not exist in the downloadedIDs array, then
                // we are not done!
                if (this._downloadedIDs.indexOf(this._updateIDs[updateIdx]) === -1) {
                    nextId = this._updateIDs[updateIdx];
                    break;
                }
            }
        }

        if (!nextId) {
            return cb();
        }

        this._spinner.start();
        this.tools.updateRobot.download(this._robotInfo, [nextId], (error, data) => {

            this._spinner.stop(true);

            if (error) {
                return cb(error);
            }

            this._downloadedIDs.push(data.id);
            this.green('Downloaded ' + data.id);

            this._startNextDownload(cb);
        });
    }

    _closeOTASocket() {
        if (this._otaSocket) {
            this._otaSocket.removeListener('message', this._downloadStatus);
            this._otaSocket.close();
            this._otaSocket = null;
        }
    }

    _downloadStatus(data) {
        try {
            data = JSON.parse(data);
        }
        catch(e) {
            this._spinner.stop(true);
            return this.red('error during download...status is not JSON');
        }
        let percentage = Math.round(data.received/data.length * 100);
        this._spinner.setSpinnerTitle('downloading update (' + data.id + ') ' + percentage + '% %s');
    }
}