import {powerOffRobot} from './dev-shell';

/**
 * Send poweroff to the robot.
 * @method module:jibo-cli.powerOff
 * @param {RobotInfo} robotInfo Robot's info.
 * @param {Function} cb Callback function.
 */
function powerOff(robotInfo, cb){
    powerOffRobot(robotInfo.ip, (error, msg) => {
        cb(error, msg);
    });
}

export default powerOff;
