import path = require('path');
import findRoot = require('find-root');

/**
 * Get the path to the root folder of the jibo-cli module.
 * @function module:jibo-cli#getToolsPath
 * @param {String} [folder1] Additional sub-folder in root.
 * @param {String} [folder2] Another additional sub-sub-folder.
 */
export default function getToolsPath(folder1?:string, folder2?:string):string {
    // get the root node module path by looking for all 
    // up to the "/lib/" folder
    const rootPath = findRoot(__dirname);
    return path.join(rootPath, folder1 || '', folder2 || '');
}