import Config from "./config";
import _ = require('lodash');

function loadConfig(cb){
    let config = new Config();
    config.load( (err) => {
        if(err){
            cb(err);
            return;
        }
        cb(null, config);
    });
}


/**
 * @namespace robots
 * @memberof module:jibo-cli
 */
const robots = {

    /**
     * List all the robots.
     * @method module:jibo-cli.robots.list
     * @param {Function} cb Callback when complete.
     */
    list: function(cb){

        loadConfig( (err, config) => {
            if(err){
                cb(err);
                return;
            }

            let robotsList = config.get("robots");
            if( Array.isArray(robotsList) ){
                cb(null, robotsList);
                return;
            } else {
                cb(null,[]);
                return;
            }
        });
    },

    /**
     * Add a robot to the list of remebered robots.
     * @method module:jibo-cli.robots.add
     * @param {String} robotName The name of the robot to add.
     * @param {String} robotIPAddress Address of the robot
     */
    add(robotName, robotIPAddress, cb){

        loadConfig( (err, config) => {
            if(err){
                cb(err);
                return;
            }

            // Validate
                // The robot's name must be at least one character long
            if( !robotName || (robotName.length === 0) ){
                cb(new Error("Robot's name must be at least one character long") );
                return;
            }
                // The robot's IP must be a valid IP address
            if( isValidIPaddress(robotIPAddress) === false ) {
                cb(new Error(`IP address is not a valid (${robotIPAddress})`));
                return;
            }

            // Get the list of current robots
            let robotsList = config.get("robots");

            if( typeof robotsList === "undefined"||
                // In case the array was somehow not an array
                Array.isArray(robotsList) === false) {
                // If there was no robots list then start a list
                robotsList = [];
            }

            // Don't allow the same robot to be added twice
            if( _.findIndex(robotsList, (robot) => (robot as any).name === robotName) !== -1 ){
                cb(new Error(`A robot with the name ${robotName} already exists. Delete it first if you want to update it's information `));
                return;
            }

            // Add new robot to the list
            robotsList.push({
                name: robotName,
                ip: robotIPAddress
            });

            // Keep the list sorted alphabetically
            robotsList.sort( (a, b) => a > b );

            // Update the configuration in memory
            config.set("robots", robotsList);

            // set it to be the default
            config.set("defaultRobot", robotName);

            // Save changes to disk
            config.save( (err) => {
                cb(err);
            });
        });
    },

    /**
     * Remove a robot from the list of remebered robots.
     * @method module:jibo-cli.robots.remove
     * @param {String} robotName The name of the robot to remove.
     * @param {Function} cb Callback when complete.
     */
    remove(robotName, cb){
        console.log('');
        loadConfig( (err, config) => {
            if(err){
                cb(err);
                return;
            }

            // Validate
                // The robot's name must be at least one character long
            if( !robotName || (robotName.length === 0) ){
                cb(new Error("Robot's name must be at least one character long") );
                return;
            }

            // Get the list of current robots
            let robotsList = config.get("robots");

            if( typeof robotsList === "undefined"||
                // In case the array was somehow not an array
                Array.isArray(robotsList) === false) {
                cb(new Error("There are no robots to delete"));
                return;
            }

            // Make sure the robot even exists
            let robotIndex = _.findIndex(robotsList, (robot) => (robot as any).name === robotName);
            if( robotIndex === -1 ){
                cb(new Error(`No robot with the name ${robotName} exists.`));
                return;
            }

            // Remove the robot from the list
            _.pullAt(robotsList, robotIndex);

            // Update the configuration in memory
            config.set("robots", robotsList);

            // Clear the defaultRobot if it was the robot that just got removed
            if( config.get("defaultRobot") === robotName) {
                config.set("defaultRobot", undefined);
            }

            // Save changes to disk
            config.save( (err) => {
                cb(err);
            });
        });
    },

    /**
     * Set the default robot to use.
     * @method module:jibo-cli.robots.setDefault
     * @param {String} robotName The name of the robot to default to.
     * @param {Function} cb Callback when complete.
     */
    setDefault(robotName, cb){
        loadConfig( (err, config) => {
            if(err){
                cb(err);
                return;
            }

            // Validate
                // The robot's name must be at least one character long
            if( !robotName || (robotName.length === 0) ){
                cb(new Error("Robot's name must be at least one character long") );
                return;
            }
                // Does the robot exist in the robots list?
            let robotsList = config.get("robots");
            if( Array.isArray(robotsList) === false ||
                _.findIndex(robotsList, (robot) => (robot as any).name === robotName) === -1 ) {
                cb(new Error(`${robotName} doesn't exist in the list of robots. Run to 'jibo robot-list' to see the list of robots`));
                return;
            }

            // Update the defaultRobot in memory
            config.set("defaultRobot", robotName);

            // Save changes to disk
            config.save( (err) => {
                cb(err);
            });
        });
    },

    /**
     * Get the default robot.
     * @method module:jibo-cli.robots.setDefault
     * @param {Function} cb Callback when complete.
     */
    getDefault(cb){
        loadConfig( (err, config) => {
            if(err){
                cb(err);
                return;
            }

            // Get the default robot if one was set
            let defaultRobot = config.get("defaultRobot");

            if( typeof defaultRobot === "undefined" ) {
                // Return null if none were set
                cb(null, null);
                return;
            }

            cb(null, defaultRobot);
        });
    },

    /**
     * Get the RobotInfo for a robot.
     * @method module:jibo-cli.robots.getInfo
     * @param {String} robotName The name of the robot.
     * @param {Function} cb Callback when complete. Return [RobotInfo](https://github.jibo.com/pages/sdk/animation-utilities/module-jibo_animate.RobotInfo.html).
     */
    getInfo(robotName, cb){

        // Validate
            // The robot's name must be at least one character long
        if( robotName.length === 0 ){
            cb(new Error("Robot's name must be at least one character long") );
            return;
        }

        // Fetch the robot list and then pull out the target
        this.list( (err, robotsList) => {
            if(err){
                cb(err);
                return;
            }

            let robotIndex = _.findIndex(robotsList, (robot:any) => robot.name === robotName);

            if(robotIndex === -1){
                cb(new Error(`No robot by the name ${robotName} exists in the robot list`));
                return;
            }

            cb(null, robotsList[robotIndex]);
        });
    }
};

export default robots;

function isValidIPaddress(ipaddress) {

    // if (/^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/.test(ipaddress)) {
    //     return true;
    // }
    // return false;
    // call him whatever you want.
    return (ipaddress ? true : false);
}
