import {spawn} from 'child_process';
import getElectronPath from '../get-electron-path';
import path = require('path');
import {EventEmitter} from 'events';
import _ = require('lodash');
import Sync from '../robots/sync';
import {stop} from 'jibo-sync';
import run from '../robots/run';
import getToolsPath from '../get-tools-path';

class SyncChild extends EventEmitter {
    kill() {
        stop();
        this.emit('exit');
    }
}

class RunChild extends EventEmitter {
    public host:string;
    constructor(host) {
        super();
        this.host = host;
    }
    kill() {
        require('../robots/stop')({ip: this.host}, () => {
            console.log('skill stopped');
        });
        this.emit('exit');
    }
}

/**
 * Launch the simulator.
 * @name module:jibo-cli#launcher
 * @type {module:jibo-cli.Launcher}
 */

/**
 * Launcher.
 * @memberof module:jibo-cli
 * @class Launcher
 * @extends EventEmitter
 */
class Launcher extends EventEmitter {

    public child:RunChild|SyncChild;

    constructor() {
        super();
        this.child = null;
    }

    /**
     * When the child process exits.
     * @method module:jibo-cli.Launcher#onChildExit
     * @private
     */
    onChildExit() {
        this.child.removeAllListeners();
        this.child = null;
        this.emit('exit');
    }

    /**
     * Play a skill on the robot. Requires sync.
     * @method module:jibo-cli.Launcher#playOnRobot
     * @param {String} host The host name.
     * @param {String} directroy Path to the skill.
     * @param {String} skillName The package.json's name of the skill.
     */
    playOnRobot(host, directory, skillName) {
        this.child = new SyncChild();
        this.child.on('exit', this.onChildExit.bind(this));
        Sync.start({ip: host}, directory, (err) => {
            console.log('Skill synced');
            this.child = null;
            if(err) {
                console.log('UPLOAD ABORTED', err);
                this.emit('upload-error');
            }
            else {
                this.child = new RunChild(host);
                this.child.on('exit', this.onChildExit.bind(this));
                run({ip: host}, skillName, (err) => {
                    if(err) {
                        console.error('launch error ' + err);
                        this.child = null;
                        this.emit('play-error');
                    }
                    else {
                        this.emit('playing');
                    }
                });
            }
        });
    }

    /**
     * Play a skill path.
     * @method module:jibo-cli.Launcher#play
     * @param {String} indexPath The path to the skill.
     * @param {String} [remoteRegistry] If included, will look for registry.
     * @param {String} [token] Management token at this location.
     */
    play(indexPath, remoteRegistry?, token = '0123456789abcdefg') {
        //console.log('indexPath', indexPath);
        //console.log('remoteRegistry', remoteRegistry);
        if(!this.child) {
            let cwd = getToolsPath('simulator');
            let args = [
                path.resolve(cwd, 'app.js'),
                '--path',
                indexPath,
                '--token',
                token
            ];
            let isRemoteMode = remoteRegistry && remoteRegistry.length > 0;
            if(isRemoteMode) {
                args.push('--remote', remoteRegistry);
            }
            const envOverrides = {
                "ELECTRON_INTERNAL_RUN_AS_NODE": "0",
                // Pass in an environmental variable to help the skill's main
                // process know which mode it's running in
                "RUNMODE": isRemoteMode ? "REMOTELY" : "SIMULATOR",
                "NODE_PATH": ""
            };

            //atom overrides parent shell's NODE_PATH
            // parent shell should set desired NODE_PATH (for use in spawned simulator) into NODE_PATH_SIM,
            // and it will be restored into NODE_PATH here for child.
            const env = process.env as any;
            if (env.hasOwnProperty("NODE_PATH_SIM")){
                if(env.hasOwnProperty("NODE_PATH")){ //both exist, combine them
                    envOverrides.NODE_PATH = env.NODE_PATH+":"+env.NODE_PATH_SIM;
                }else{ //only NODE_PATH_SIM exists, use it
                    envOverrides.NODE_PATH = env.NODE_PATH_SIM;
                }
            }
            this.child = spawn(
                getElectronPath(),
                args,
                {
                    cwd: cwd,
                    env: _.assign({}, process.env, envOverrides)
                }
            );

            // let onData = (data) => {
            //     console.info(data.toString());
            // };
            //
            // this.child.stderr.on('data', onData);
            // this.child.stdout.on('data', onData);

            this.emit('start');
            this.child.on('error', function(error) {
                console.log(error);
            });
            this.child.on('exit', this.onChildExit.bind(this));
        }
    }

    /**
     * Stop a skill from playing.
     * @method module:jibo-cli.Launcher#stop
     */
    stop() {
        if(this.child) {
            console.log("STOP");
            this.child.on('error', function(event) {
                console.log(event);
            });
            this.child.kill();
        }
    }
}


export default new Launcher();
