import {deleteSkill} from './dev-shell';
/**
 * Delete a skill on the robot.
 * @method module:jibo-cli.delSkill
 * @param {RobotInfo} robotInfo The robot to delete the skill from.
 * @param {String} skillName Name of the skill to delete from the robot.
 */
function delSkill(robotInfo, skillName, cb){

    deleteSkill(robotInfo.ip, skillName, (error, msg) => {
        cb(error, msg);
    });
}

export default delSkill;
