import program = require('commander');
import tools from '../jibo-tools';
import colors = require('colors');

/**
 * @description All sub-commands extend this Class.
 * @class Command
 * @memberof module:jibo-cli.cli
 */
export default class Command {

    public tools:typeof tools;
    public program:any;

    constructor() {

        /**
         * The tools commands.
         * @name module:jibo-cli.cli.Command#tools
         * @type {Object}
         */
        this.tools = tools;

        /**
         * The commander program used to organized CLI commands.
         * @name module:jibo-cli.cli.Command#program
         * @type {commander}
         */
        this.program = program;

        this.parse();
        this.exec();
    }

    /**
     * Parse the arguments.
     * @method module:jibo-cli.cli.Command#parse
     * @param {commander} program Commander instance.
     */
    parse() {
        this.program.parse(process.argv);
    }

    /**
     * Execute a command.
     * @method module:jibo-cli.cli.Command#exec
     */
    exec() {
        throw new Error("Invalid command setup");
    }

    /**
     * Get the robot info by the robot name.
     * @method module:jibo-cli.cli.Command#fetchRobot
     * @param {String} robotName The name of the robot.
     * @param {Function} callback Callback when complete.
     */
    fetchRobot(robotName, cb) {
        this.tools.robots.getInfo(robotName, (err, robotInfo) => {
            if (err) {
               return this.error(err); 
            }
            cb(robotInfo);
        });
    }

    /**
     * Call this when an error occurs and the process should exit. Prints out
     * the error's message in a consistent way.
     * @method module:jibo-cli.cli.Command#error
     * @param {Error|String} error Error whose message will be logged out to the console.
     */
    error(error) {
        this.red(error);
        process.exit(1);
    }

    /**
     * Call a warning.
     * @method module:jibo-cli.cli.Command#warn
     * @param {String} message Warning for the console.
     */
    warn(message) {
        console.log(colors.yellow("\n" + message + "\n"));
    }

    /**
     * Exit process with a successful exit code and print out the message.
     * @method module:jibo-cli.cli.Command#success
     * @param message {String} Message to log out to the console. If not provided,
     *                         no message will be logged.
     */
    success(message?) {
        if (message) {
            this.green(message);
        }
        process.exit();
    }

    /**
     * Output a message in green to the command line.
     * @method module:jibo-cli.cli.Command#green
     * @param {String} message Message to output.
     */
    green(message) {
        console.log(colors.green("\n" + message + "\n"));
    }

    /**
     * Output a message in red to the command line.
     * @method module:jibo-cli.cli.Command#red
     * @param {String} message Message to output.
     */
    red(message) {
        console.log(colors.red("\n" + message + "\n"));
    }

    /**
     * Check to see if a robot is reachable.
     * @method module:jibo-cli.cli.Command#isRobotReachable
     * @param {String} robotName The info of the robot the user wants to connect to.
     * @param {Function} success Callback upon success. Return [RobotInfo](https://github.jibo.com/pages/sdk/animation-utilities/module-jibo_animate.RobotInfo.html).
     */
    isRobotReachable(robotName, message, cb) {

        this.getRobotInfo(robotName, (robotInfo) => {

            if (message) {
                this.green(message.replace("%s", robotInfo.name));
            }

            /**
             * Takes an array of objects with identical fields and prints them out in a nicely
             * formated table
             */
            this.tools.networks.isRobotReachable(robotInfo, (err, reachable) => {
                if (err) {
                    return this.error(err);
                }

                if (reachable === false) {
                    this.error("Could not connect to " + robotInfo.name + ". Make sure the robot is turned on.");
                } else {
                    cb(robotInfo);
                }
            });
        });
    }

    /**
     * Get the robot info by name.
     * @method module:jibo-cli.cli.Command#getRobotInfo
     * @param {String} robotName
     * @param {Function} callback Callback with [RobotInfo](https://github.jibo.com/pages/sdk/animation-utilities/module-jibo_animate.RobotInfo.html) as the argument
     */
    getRobotInfo(robotName, cb) {

        // If no robotName was provided, fetch the default robotName if there is one
        if (typeof robotName === "undefined") {
            this.tools.robots.getDefault((err, defaultRobotName) => {
                if (err) {
                    return this.error(err);
                }

                // If no default robot exists, we can't do anything. Early out and communicate
                // the issue to the user with a suggested solution
                if (defaultRobotName === null) {
                    return this.error(new Error("No default robot was set. Call 'jibo set-default-robot <robotName>' to set a default."));
                }
                this.fetchRobot(defaultRobotName, cb);
            });
        } else {
            this.fetchRobot(robotName, cb);
        }
    }
}
