import {exec} from 'child_process';
import Command from '../command';

/**
 * Run the skill in the simulator.
 * @class Sim
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Sim extends Command {
    parse() {
        this.program
            .option('-r, --remote <address> <n>', 'Run this as a remote simulation')
            .parse(process.argv);
    }

    exec() {
        this.tools.validateSkillPath(this.program.args[0], (err, skillPath, skillName) => {
            if (err) {
                return this.error(err);
            }
            this.sim(skillPath, skillName);
        });
    }
    sim(skillPath, skillName) {
        // Make sure the working directory is the skill's root
        exec("cd " + skillPath,
            (err) => {
                if (err) {
                    return this.error(err);
                }
                this.green("Running skill named " + skillName + ", located at " + skillPath + ". Press control+c to quit");
                let indexPath = skillPath + "/index.html";
                if (this.program.remote && this.program.remote.length > 0) {
                    this.tools.launcher.play(indexPath, this.program.remote);
                }
                else {
                    this.tools.launcher.play(indexPath);
                }
            }
        );
    }
}