import {spawn} from "child_process";

/**
 * @namespace networks
 * @memberof module:jibo-cli
 */
const networks = {
    /**
     * Check if a robot will be reachable for subsequent ssh-related commands, like
     * `jibo ssh`, `jibo sync`, `jibo debug`, etc.
     * @method module:jibo-cli.networks.isRobotReachable
     * @param {RobotInfo} robotInfo Information fetched from `robots.getInfo()`.
     * @param {Function} cb Callback function when complete.
     */
    isRobotReachable(robotInfo, cb) {
        let exited = false; // unfortunately, need this so we don't call our cb more than once

        let args = '-t 10';
        if (process.platform === 'win32') {
            args = '-4'; // forces ipv4 ping
        }
        let ping = spawn("ping", [args, robotInfo.ip], ['pipe']),
            errOutput = "";

        ping.on('close', () => {
            if (!exited) {
                ping.kill('SIGKILL');
                cb(null, false);
                exited = true;
            }

            return;
        });

        ping.on('exit', () => {
            if (!exited) {
                ping.kill('SIGKILL');
                cb(null, false);
                exited = true;
            }

            return;
        });

        // Listen for bounced pings related messages
        ping.stderr.on('data', (data) => {

            // request timeout? (robot isn't reachable)
            errOutput += data.toString();

            //process.stdout.write("error " + data);

            if( errOutput.search("No route to host") !== -1 ||
                errOutput.search("Host is down")  !== -1 ) {

                if (!exited) {
                    ping.kill('SIGKILL');
                    cb(null, false);
                    exited = true;
                }

                return;
            }
        });

        // Collect output and check if the text is indicating ping responses
        // are returning
        let output = "";
        ping.stdout.on('data', (data) => {

            output += data.toString();

            //process.stdout.write("data: " + data);
            let searchString = "bytes from";
            if (process.platform === 'win32') {
                searchString = "bytes=";
            }

            if(output.search(searchString) !== -1) {

               if (!exited) {
                    ping.kill('SIGKILL');
                    cb(null, true);
                    exited = true;
                }

                return;
            }
        });
    }
};

export default networks;
