import Command from '../command';
import path = require('path');

/**
 * Intialize, create a skeleton project.
 * @class Init
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Init extends Command {
    parse() {
        this.program
            .description('Creates a jibo skeleton project.')
            .option('-t, --type [package-type]',
                "The type of project: 'behavior-template', 'asset-pack-template'\nDefault is 'behavior-template'",
                /^(behavior-template|asset-pack-template)$/i,
                'behavior-template')
            .parse(process.argv);
    }
    
    exec() {

        // If no skill was passed, then attempt to use the current directory's name
        let packagePath = this._resolveSkillPath(this.program.args[0]);
        this.green("Creating package: " + packagePath);

        // get title of skill from directory
        let dirs = packagePath.split(path.sep);
        let title = (dirs.length > 0 ? dirs[dirs.length - 1] : packagePath);
        this.tools.packageGenerator(this.program.type, packagePath, title, "", (err) => {
            if (err) {
                return this.error(err);
            }
            this.green("Done");
        });
    }

    _resolveSkillPath(skillPath){
        // Get the absolute path in case a relative path was passed in
        if( typeof skillPath === "string"){
            return path.resolve(process.cwd(), path.normalize(skillPath));
        }
        // Use the current directory if no path was provided
        else {
            return process.cwd();
        }
    }
}