import Command from '../command';

/**
 * Reboot the robot.
 * @class Reboot
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Reboot extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Rebooting %s.", (robotInfo) => {
            this.tools.reboot(robotInfo, (err, msg) => {
                if (err) {
                    return this.error(err);
                }
                this.success(msg);
            });
        });
    }
}