import {stopSkill} from './dev-shell';

/**
 * Stop any running skill on the robot.
 * @method module:jibo-cli.stop
 * @param {RobotInfo} robotInfo The robot to stop the skill on.
 * @param {Function} cb Callback when complete.
 */
function stop(robotInfo, cb){

    stopSkill(robotInfo.ip, (error, msg) => {
        cb(error, msg);
    });
}

export default stop;
