import validateSkillPath from "./validate-skill-path";
import {syncSkill, stopSync} from './dev-shell';

/**
 * @namespace sync
 * @memberof module:jibo-cli
 */

/**
 * Copy all the files to a robot.
 * @method module:jibo-cli.sync.start
 * @param {RobotInfo} robotInfo [RobotInfo](https://github.jibo.com/pages/sdk/animation-utilities/module-jibo_animate.RobotInfo.html) for the target robot.
 * @param {String} skillPath Path to skill folder that is to be copied/synced onto
 *                           a robot. If not specified, sync will check if the current
 *                           directory is a valid app and then sync that.
 */
export default class Sync {

    static start(robotInfo, skillPath, cb) {

        // Make sure the skill path is a valid skill
        validateSkillPath(skillPath, (err, skillPath, skillName) => {
            if (err) {
                cb(err, null);
                return;
            }

            let verbose = true;
            syncSkill(robotInfo.ip, skillPath, skillName, verbose, (error, msg) => {
                cb(error, msg);
            });
        });
    }

    /**
     * Copy all of the files over of a robot
     * @method module:jibo-cli.sync.stop
     * @param {RobotInfo} robotInfo Robot info of the target robot
     * @param {Function} callback Callback when stopped.
     */
    static stop(robotInfo, cb) {
        stopSync(robotInfo.ip, (error, msg) => {
            cb(error, msg);
        });
    }
}