import Command from '../command';

/**
 * Re-index the robot.
 * @class Index
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Index extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Indexing %s.", (robotInfo) => {
            this.tools.index(robotInfo, (err, msg) => {
                if (err) {
                    return this.error(err);
                }
                this.success(msg);
            });
        });
    }
}