import Command from '../command';

/**
 * Set the robot volume.
 * @class SetVolume
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class SetVolume extends Command {
    parse() {
        this.program
            .option('-r, --robot <n>', 'Target robot')
            .parse(process.argv);
    }

    exec() {
        this.isRobotReachable(this.program.robot, "Setting the volume of %s.", (robotInfo) => {
            this.tools.volume.set(robotInfo, process.argv[2], (err, volume) => {
                if (err) {
                    return this.error(err);
                }
                this.success(robotInfo.name + "'s volume was successfully set to: " + volume);
            });
        });
    }
}