import Command from '../command';

/**
 * Remove a robot from list of remembered robots.
 * @class RemoveRobot
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class RemoveRobot extends Command {
    exec() {
        this.tools.robots.remove(process.argv[2], (err) => {
            if (err) {
                return this.error(err);
            }
            this.success(process.argv[2] + " success removed.");
        });
    }
}
