import Command from '../command';

/**
 * Power off the robot.
 * @class Poweroff
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Poweroff extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Powering off %s.", (robotInfo) => {
            this.tools.powerOff(robotInfo, (err, msg) => {
                if (err) {
                    return this.error(err);
                }
                this.success(msg);
            });
        });
    }
}
