import path = require('path');
import resolve = require('resolve');
import electronPath = require('electron-prebuilt');

/**
 * Returns where the electron executable is
 *
 * We have to reimplement this versus just using 'const path = require('electron-prebuilt');' because
 * when jibo-tools is installed via Atom's UI or 'apm install' all modules are installed temporarily in a temp
 * directory and then moved somewhere else if successful, this breaks electron-prebuilts postinstall logic
 * that saves out a file that includes the path to the electron executable.
 *
 * NOTE: An issue has been filed to the electron-prebuilt project, so we may be able to remove this eventually:
 * https://github.com/electron-userland/electron-prebuilt/issues/99
 * @function module:jibo-cli#getElectronPath
 * @return {String} The full path to electron prebuilt.
 */
function getElectronPath() {

    const modName:string = 'electron-prebuilt';

    // Get the path to the platform-specific version of electron
    const exec:string = electronPath.substr(electronPath.indexOf(modName) + modName.length);

    // Resolve the root directory of electron
    const roothPath:string = path.dirname(resolve.sync('electron-prebuilt'));

    // Recreate what's normally postinstalled to electron-prebuilt/path.txt
    return roothPath + exec;
}
export default getElectronPath;
