import {setVolume, getVolume} from './dev-shell';

/**
 * @namespace volume
 * @memberof module:jibo-cli
 */
const volume = {
    /**
     * Get the sound volume of a robot.
     * @method module:jibo-cli.volume.get
     * @param {RobotInfo} robotInfo Robot whose volume we want to get.
     * @param {Function} cb Async call back in the form `function(err, volume){}`
     */
    get(robotInfo, cb){
        getVolume(robotInfo.ip, (error, msg) => {
            cb(error, msg);
        });
    },

    /**
     * Set the sound volume of a robot.
     * @method module:jibo-cli.volume.set
     * @param {RobotInfo} robotInfo Robot whose volume we want to set.
     * @param {String|Number} volume Volume to set, should be in the range `(0-255)`.
     * @param {Function} cb Async call back in the form `function(err){}`
     */
    set(robotInfo, volume, cb){
        setVolume(robotInfo.ip, volume, (error, msg) => {
            cb(error, msg);
        });
    }
};

export default volume;
