/**
 * Simple config serialization library
 * TODO: Extract this into it's own module and add support
 * for having global versus local configs with local overriding the global
 * this may end up being like .jshintrc (.jiborc ?)
 */

import fs = require('fs');
import path = require('path');
import {EventEmitter} from "events";
import ensureDir = require('ensureDir');
import osenv = require('osenv');

let configPath = path.resolve(osenv.home(), ".jibo/cli.json");

class Config extends EventEmitter {

    public settings:any;

    constructor() {
        super();
        this.settings = {};
    }

    load(cb){

        fs.readFile(configPath, 'utf8', (err, fileContents) => {

            if(err) {
                this.settings = {};
                cb(null);
                return;
            }

            // Make sure it can be parsed
            try{
                let configSettings = JSON.parse(fileContents as string);
                this.settings = configSettings;
            } catch(e){
                console.log('parse error');
                console.log(e);
                cb(e);
            }

            cb(null);
        });
    }

    save(cb){
        // Ensure the path exists and then write the file
        ensureDir(path.dirname(configPath), null, () => {
            fs.writeFile(configPath, JSON.stringify(this.settings, null, "  "), function(err){
                cb(err);
            });
        });

    }

    /**
     * Takes a variable amount of parameters that are strings that indicate
     * the path of a field that the caller wants to get. It will return undefined if
     * that field does not exist.
     *
     * Returns the top level settings if no paths are specified
     */
    get(){
        if(arguments.length === 0){
            return this.settings;
        }

        let currentPath = this.settings;

        for(let i = 0; i<arguments.length; i++){

            if(typeof currentPath[arguments[i]] !== "undefined"){
                currentPath = currentPath[arguments[i]];
            } else {
                return undefined;
            }
        }
        return currentPath;
    }

    /**
     * Takes a variable amount of parameters that are strings that indicate
     * the path of a field that the caller wants to set. It will create the necessary
     * nested objects if they don't exist.
     *
     * If no paths are specified than the top level settings will be replaced
     * with the provided value
     *
     * set(path1, path2, ..., value)
     */
     set(value){
         if(arguments.length === 0){
             throw new Error("No value was provided to Config.set()");
         } else if(arguments.length === 1){
             this.settings = value;
         }

         let currentPath = this.settings;

         for(let i = 0; i<(arguments.length-2); i++){
             console.log('path ' + arguments[i]);
             // Does the path exist or is an array
             if( typeof currentPath[arguments[i]] === "undefined" ||
                 Array.isArray(currentPath[arguments[i]]) ){
                 // For now arrays get replaced with objects to enable a path
                 // TODO: Reevaluate if we should support pathing into arrays too
                 currentPath[arguments[i]] = {};
             }
             currentPath = currentPath[arguments[i]];
         }

         currentPath[arguments[arguments.length-2]] = arguments[arguments.length-1];
     }
}

export default Config;
