import Command from '../command';

/**
 * Get the build version on the robot.
 * @class BuildVersion
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class BuildVersion extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Fetching the buildroot version of %s.", (robotInfo) => {
            this.tools.buildVersion(robotInfo, (err, buildVersion) => {
                if (err) {
                    return this.error(err);
                }
                this.success(buildVersion);
            });
        });
    }
}