import program = require('commander');
import path = require('path');
import hamming = require('compute-hamming');
import colors = require('colors');

/**
 * Main entry point for the CLI commands.
 * @class Main
 * @memberof module:jibo-cli.cli
 * @param {String} binDir Path to the folder with other commands.
 */
export default class Main {

    public knownSubCommands:Array<string[]>;
    public rootPath:string;

    constructor(binDir) {
        // We make a white list of known sub commands as commander will fail silently
        // when you miss spell a command. So we add the functionality to detect and
        // notify the users of miss spellings. Additionally we add git like support
        // to give a best guess as to the sub command they meant to type
        this.knownSubCommands = [
            // first entry: the sub command
            // second entry: the parameters it takes
            // third entry:  a high level description
            ["init", "[path] [--type]", "Create a new project (skill|asset pack)."],
            ["sim", "[path] [--remote]", "Launch a skill in the simulator."],
            ["robot-list", "", "Display the list of robots this machine is connected to."],
            ["add-robot", "<robotName> <robotIpAddress>", "Add a robot to my robot list."],
            ["remove-robot", "[robotName]", "Remove a robot from my robot list."],
            ["set-default-robot", "[robotName]", "Set the default robot to be used when a robot is not specified."],
            ["update-robot", "[--robot] [--filter]", "Download and install available updates on a robot."],
            ["sync", "[skillPath] [--robot]", "Sync a skill to a robot."],
            ["run", "[skillPath] [--robot] [--nosync] [--verbose]", "Run a skill on a robot."],
            ["delete", "[skillPath] [--robot]", "Delete a skill from a robot."],
            ["debug", "", "[Deprecated.]"],
            ["stop", "[robotName]", "Stop any skills currently running on a robot."],
            ["diskspace", "[robotName]", "Display the amount of storage space on a robot."],
            ["build-version", "[robotName]", "Display the buildroot version installed on a robot."],
            ["set-volume", "<volume> [--robot]", "Set the volume of a robot."],
            ["get-volume", "[robotName]", "Display the current volume of a robot."],
            ["index", "[robotName]", "Index a robot. (Required after powering robot on.)"],
            ["reboot", "[robotName]", "Restart a robot."],
            ["poweroff", "[robotName]", "Power off a robot."],
            ["help", "[command]", "Display help for the specified command."],

            // We need to whitelist the built in sub commands too
            // Add the built in commands to the known sub commands list
            ["-h"],
            ["--help"],
            ["help"],
            ["-V"],
            ["--version"]
        ];

        this.rootPath = path.dirname(binDir);
        this.parse();
        this.validate();
    }

    /**
     * Pars the commands.
     * @method module:jibo-cli.cli.Main#parse
     */
    parse() {

        let packageInfo = require(path.join(this.rootPath, 'package.json'));

        // Tell commander our version number, this is pulled out package.json
        let chain = program.version(packageInfo.version);

        // Simulate chaining each call subsequently with each sub command in our list
        this.knownSubCommands.forEach((subCommand) => {

            // Don't call command() on our built in commands entries. They only have
            // have one entry in their list, so we can detect them
            if (subCommand.length !== 1){
                chain = chain.command(subCommand[0] + " " + subCommand[1], subCommand[2]);
            }
        });

        // Finally parse the args
        chain.parse(process.argv);
    }

    /**
     * Echo out a yellow-colored log.
     * @method module:jibo-cli.cli.Main#yellow
     * @param {String} message The message to show.
     */
    yellow(message) {
        console.log(colors.yellow(message));
    }

    /**
     * Check for incorrect commands.
     * @method module:jibo-cli.cli.Main#validate
     */
    validate() {

        // Detect if the sub command was missspelled
        let found;
        this.knownSubCommands.forEach((subCommand) => {
            if(process.argv[2] === subCommand[0]){
                found = true;
            }
        });

        // Not found, notify user of their miss spelling and suggest the closest match
        // and how to find the list of commands
        if (!found) {

            let closestSubCommands = [];

            // Find the closest match
            let closestDistance = Number.MAX_SAFE_INTEGER;
            this.knownSubCommands.forEach((subCommand) => {
                // hamming() requires the commands to be of the same length. So we need to
                // to clip the longer one and consider each clipped character to be one edit
                let string1 = subCommand[0];
                let string2 = process.argv[2];
                let distance = 0;

                if (string1.length < string2.length) {
                    distance = string2.length - string1.length;
                    string2 = string2.slice(0,string1.length);

                } else if (string1.length > string2.length) {
                    distance = string1.length - string2.length;
                    string1 = string2.slice(0, string2.length);
                }

                distance += hamming(string1, string2);

                if (distance < closestDistance) {
                    closestDistance = distance;
                    closestSubCommands = [subCommand[0]];
                }
            });

            this.yellow("jibo: '" + process.argv[2] + "' is not a jibo command. See 'jibo --help' for the list of commands.");
            this.yellow("");

            if (closestSubCommands.length === 0){
                this.yellow("Did you mean this?");
            } else {
                this.yellow("Did you mean one of these?");
            }

            closestSubCommands.forEach((subCommand) => {
                this.yellow("   " + subCommand);
            });
        }
    }
}
