import {rebootRobot} from './dev-shell';

/**
 * Send reboot signal to the robot.
 * @method module:jibo-cli.reboot
 * @param {RobotInfo} robotInfo Robot's info.
 * @param {Function} cb Callback function.
 */
function reboot(robotInfo, cb){
    rebootRobot(robotInfo.ip, (error, msg) => {
        cb(error, msg);
    });
}

export default reboot;
