import {checkForUpdates, downloadUpdates, installUpdates, getOTASocketUrl} from './dev-shell';

let update = {

    get(robotInfo, filter, cb){
        checkForUpdates(robotInfo.ip, filter, cb);
    },

    download(robotInfo, ids, cb){
        downloadUpdates(robotInfo.ip, ids, cb);
    },

    install(robotInfo, ids, cb){
        installUpdates(robotInfo.ip, ids, cb);
    },

    getOTASocketUrl(robotInfo):string {
        return getOTASocketUrl(robotInfo.ip);
    }
};

export default update;
