import Command from '../command';

/**
 * Sync a skill to the robot.
 * @class Sync
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Sync extends Command {
    parse() {
        this.program
            .option('-r, --robot <n>', 'Target robot')
            .parse(process.argv);
    }
    
    exec() {
        this.isRobotReachable(this.program.robot, "Attempting to sync a skill to %s. Press CTRL+C to cancel.", (robotInfo) => {
            this.tools.sync.start(robotInfo, this.program.args[0], (err, msg) => {
                if (err) {
                    return this.error(err);
                }
                if (msg) {
                    this.green(msg);
                }
                let finalMsg = "Skill synced success to '" + robotInfo.name + "'. To launch the skill run:  'jibo run'";
                this.success(finalMsg);
            });
        });
    }
}