import Command from '../command';

/**
 * Set the default robot to use when running jibo commands.
 * @class SetDefaultRobot
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class SetDefaultRobot extends Command {
    exec() {
        this.tools.robots.setDefault(process.argv[2], (err) => {
            if (err) {
                return this.error(err);
            }
            this.success(process.argv[2] + " is now the default robot.");
        });
    }
}
