import {getDiskSpace} from './dev-shell';

/**
 * Get the diskspace on the robot.
 * @method module:jibo-cli.diskSpace
 * @param {RobotInfo} robotInfo Robot's info.
 * @param {Function} cb Callback function.
 */
function diskSpace(robotInfo, cb){

    getDiskSpace(robotInfo.ip, (error, msg) => {
        cb(error, msg);
    });
}

export default diskSpace;
