import Command from '../command';

/**
 * Run a skill on the robot.
 * @class Run
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Run extends Command {
    parse() {
        this.program
            .option('-r, --robot <n>', 'Target robot')
            .option('-v, --verbose', 'Output more information during command execution')
            .option('-n, --nosync', 'If set, skip syncing')
            .parse(process.argv);
    }

    exec() {
        this.isRobotReachable(this.program.robot, "Attempting to run a skill on %s. Press CTRL+C to cancel.", (robotInfo) => {
            // If no skill was passed, then attempt to use the current directory's name
            this.tools.validateSkillPath(this.program.args[0], (err, skillPath, skillName) => {
                if (err) {
                    return this.error(err);
                }
                
                // Do not run sync first if the nosync flag was set
                if (this.program.nosync === true) {
                    this._run(robotInfo, skillName);
                }
                // sync first
                else {
                    this.tools.sync.start(robotInfo, skillPath, (err, msg) => {
                        if (err) {
                            return this.error(err);
                        }

                        this.green(msg);
                        this._run(robotInfo, skillName);
                    });
                }
            });
        });
    }

    _run(robotInfo, skillName) {
        this.green("Launching skill");
        this.tools.run(robotInfo, skillName, (err, msg) => {
            if (err) {
                return this.error(err);
            }
            this.success(msg);
        });
    }
}