import Command from '../command';

/**
 * Debug a skill on the robot.
 * @class Debug
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Debug extends Command {
    exec() {
        this.isRobotReachable(this.program.robot, null, (robotInfo) => {
            this.tools.debug(robotInfo, null, (err) => {
                return this.warn(err);
            });
        });
    }
}