import Command from '../command';

/**
 * Get the diskspace available on the robot.
 * @class Diskspace
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Diskspace extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Fetching storage space info for %s.", (robotInfo) => {
            this.tools.diskSpace(robotInfo, (err, diskSpaceInfo) => {
                if (err) {
                    return this.error(err);
                }
                this.success(diskSpaceInfo);
            });
        });
    }
}
