import Command from '../command';

/**
 * Get the volume of the robot.
 * @class GetVolume
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class GetVolume extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Getting the volume of %s.", (robotInfo) => {
            this.tools.volume.get(robotInfo, (err, volume) => {
                if (err) {
                    return this.error(err);
                }
                this.success(robotInfo.name + "'s volume is: " + volume);
            });
        });
    }
}