/**
 * Validates that a skillPath contains a valid skill. Useful for catching
 * user errors trying to 'run' or 'sync' skills from the wrong directories
 */
 import path = require('path');
 import fs = require('fs');

/**
 * Compute the absolute path of a skill.
 * @method module:jibo-cli.resolveSkillPath
 * @param {String} skillPath Path users passed into our system. Returns the absolute path version of `skillPath`.
 */
function resolveSkillPath(skillPath){
    // Get the absolute path in case a relative path was passed in
    if( typeof skillPath === "string"){
        return path.resolve(process.cwd(), skillPath);
    }
    // Use the current directory if no path was provided
    else {
        return process.cwd();
    }
}

/**
 * Sanity checks that a given relative or absolute skill path is a valid skill folder.
 * @method module:jibo-cli.validateSkillPath
 * @param {String} skillPath Relative or absolute path to a skill's root folder.
 * @param {Function} cb Asynchronous callback in the form of `function(err, skillPath, skillName);`
 */
function validateSkillPath(skillPath, cb){

    // Convert skillPath to absolute path
    skillPath = resolveSkillPath(skillPath);

    // Verify that the folder even exists
    fs.lstat(skillPath, (err, stats) => {

        if(err){
            // Intercept folder ENOENT errors (indicating there is no file or folder there)
            if(err.errno === -2){
                cb(new Error(`No folder exists at ${skillPath}`));
                return;
            } else {
                cb(err);
                return;
            }
        }

        // Make sure it's a folder not a file
        if( stats.isDirectory() === false ) {
            cb(new Error(`${skillPath} is a file not a directory`));
            return;
        }

        // Now do some sanity checks to ensure it's a path to a skill's root directory
            // Ensure it has a package.json and that the jibo module is in it's dependencies
        fs.readFile(path.resolve(skillPath, "package.json"), "utf8", function (err, data) {

            if(err){
                // Intercept folder ENOENT errors (indicating there is no file or folder there)
                if(err.errno === -2){
                    cb(new Error(`No 'package.json' exists at ${skillPath}/package.json`));
                    return;
                } else {
                    cb(err);
                    return;
                }
            }

            // Ensure the package.json parses as json
            let packageJson;
            try{
                packageJson = JSON.parse(data);
            } catch(e){
                cb(new Error(`Error parsing skill's 'package.json' at ${skillPath}/package.json`));
                return;
            }

            /*
             * For now disable this, as it makes it so that non jibo electron apps can work with jibo run/debug/sim, otherwise
             * it would not work without having to put a fake "jibo" entry in your package.json's dependencies object
            // Ensure jibo is in the "dependencies" field
            if( typeof packageJson.dependencies !== "object" ||
                Array.isArray(packageJson.dependencies) === true ||
                typeof packageJson.dependencies['jibo'] === "undefined"
                ){

                cb(new Error(`Not a valid skill folder. 'jibo' should be listed in the "dependencies" property in ${skillPath}/package.json`));
                return;
            }
            */

            // Ensure the skill has a proper "name" set in package.json
            if( typeof packageJson.name !== "string" &&
                packageJson.name.length !== 0) {
                cb(new Error(`Skill hasn't properly set the "name" field in ${skillPath}/package.json`));
                return;
            }

            let skillName = packageJson.name;

            cb(null, skillPath, skillName);
        });
    });
}

export default validateSkillPath;
