import Command from '../command';

/**
 * Delete a skill from the robot.
 * @class Delete
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Delete extends Command {
    parse() {
        this.program
            .option('-r, --robot <n>', 'Target robot')
            .parse(process.argv);
    }

    exec() {
        this.isRobotReachable(this.program.robot, "Attempting to delete a skill from %s. Press CTRL+C to cancel.", (robotInfo) => {
            // If no skill was passed, then attempt to use the current directory's name
            this.tools.validateSkillPath(this.program.args[0], (err, skillPath, skillName) => {
                if (err) {
                    return this.error(err);
                }

                this.tools.delSkill(robotInfo, skillName, (err, msg) => {
                    if (err) {
                        return this.error(err);
                    }
                    this.success(msg);
                });
            });
        });
    }
}