import Command from '../command';

/**
 * Stop a skill running on the robot.
 * @class Stop
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class Stop extends Command {
    exec() {
        this.isRobotReachable(process.argv[2], "Attempting to stop skill running on %s.", (robotInfo) => {
            this.tools.stop(robotInfo, (err, msg) => {
                if (err) {
                    return this.error(err);
                }
                this.success(msg);
            });
        });
    }
}
