import Command from '../command';

/**
 * Generate a list of all remembered robots on this machine.
 * @class RobotList
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class RobotList extends Command {
    exec() {
        this.tools.robots.list((err, robotList) => {
            if (err) {
                return this.error(err);
            }
            if (robotList.length === 0) {
                this.success("Your robot list is empty. To add a robot, run: \n\n   jibo add-robot <robotName> " +
                    "<robotIpAddress>\n");
            }
            // Mark the default robot with a '*' in the list if there is a default set
            this.tools.robots.getDefault((err, defaultRobotName) => {
                if (err) {
                    return this.error(err);
                }
                // Add two spaces to the left of the robot names, so that there is space
                // to mark the default robot with an '*' character
                robotList.forEach((robot) => {
                    if (robot.hasOwnProperty('network')) {
                        // remove it...
                        delete robot.network;
                    }
                    if (robot.name === defaultRobotName) {
                        robot.name = "* " + robot.name;
                    } else {
                        robot.name = "  " + robot.name;
                    }
                    // Also change the name of 'name' to '  name' to line up the name
                    // label with our newly added two spaces
                });
                this.green('List of robots:');
                // Display the robot list using the built in table output function
                this.printTable(robotList, {
                    name: "  "
                });
                this.success();
            });
        });
    }

    /**
     * Takes an array of objects with identical fields and prints them out in a nicely
     * formated table
     */
    /**
     * Print out a nicely formatted table
     * @method module:jibo-cli.cli.RobotList#printTable
     * @param list (Array) Array of objects with the same fields
     * @param extraSpaces (Object)[Optional] If provided contains a look up table of
     *                                       extra spaces to add before each column label
     *                                       This is used to compensate for any extra markings
     *                                       added to the left of row values (See how the default robot is marked with a '* ')
     */
    printTable(listOfObjects, extraSpaces) {
        let maxLengths = {},
            field, i, adjustedField;

        if (listOfObjects.length === 0) {
            return;
        }

        function addExtraSpaces(field) {
            if (typeof extraSpaces !== "undefined" &&
                typeof extraSpaces[field] !== "undefined") {
                return extraSpaces[field];
            } else {
                return "";
            }
        }

        // Calculate the max characters per column
        for (field in listOfObjects[0]) {
            adjustedField = addExtraSpaces(field) + field;

            // Find the entry with the longest text for this field,
            // including the column labels themselves)
            maxLengths[field] = adjustedField.length;
            for (i = 0; i < listOfObjects.length; i++) {
                if (listOfObjects[i][field] && (listOfObjects[i][field].length > maxLengths[field])) {
                    maxLengths[field] = listOfObjects[i][field].length;
                }
            }
        }

        // Returns a string of 'n' amount of spaces
        function remainingSpace(n) {
            let spaces;
            if (n) {
                spaces = Array(n + 1).join(" ");
            }
            // We have to have a special case for zero because the Array(n).join(" ")
            // generates one less space than we want, so we add 1 to it. But in the case
            // of n===0 we just want an empty string
            else {
                spaces = "";
            }
            return spaces;
        }

        // Display list including column labels in header
        let
        // Add an extra character for spacing)
            rightMargin = Array(6).join(" "),
            columnLabels = "";
        for (field in listOfObjects[0]) {
            adjustedField = addExtraSpaces(field) + field;

            // Make sure column lables line up with the entries below
            // (add an extra character for spacing)
            columnLabels += adjustedField + remainingSpace(maxLengths[field] - adjustedField.length) + rightMargin;
        }
        console.log(columnLabels);

        // Now print out a row for every entry
        for (i = 0; i < listOfObjects.length; i++) {
            let row = "";
            for (field in listOfObjects[0]) {
                // Make sure column entries line up

                row += listOfObjects[i][field] + remainingSpace(maxLengths[field] - listOfObjects[i][field].length) + rightMargin;
            }

            console.log(row);
        }
        console.log('');
    }
}
