import Command from '../command';

/**
 * Add a robot to the list of remembered robots.
 * @class AddRobot
 * @extends module:jibo-cli.cli.Command
 * @memberof module:jibo-cli.cli
 */
export default class AddRobot extends Command {
    exec() {
        this.tools.robots.add(process.argv[2], process.argv[3], (err) => {
            if (err) {
                return this.error(err);
            }
            this.success(process.argv[2] + " success added.");
        });
    }
}