import {indexRobot} from './dev-shell';

/**
 * Re-index the robot.
 * @method module:jibo-cli.index
 * @param {RobotInfo} robotInfo Robot's info.
 * @param {Function} cb Callback function.
 */
function index(robotInfo, cb){
    indexRobot(robotInfo.ip, (error, msg) => {
        cb(error, msg);
    });
}

export default index;
