import {getBuildVersion} from './dev-shell';

/**
 * Get the robot's build version.
 * @method module:jibo-cli.buildVersion
 * @param {RobotInfo} robotInfo The robot to get a build version for.
 */

function buildVersion(robotInfo, cb){

    getBuildVersion(robotInfo.ip, (err, versionInfo) => {
        cb(err, versionInfo);
    });
}

export default buildVersion;
